string mergeAlternately(string w1, string w2) {
    string out;
    size_t i = 0;
    for (; i < w1.size() && i < w2.size(); i++) {
        out += w1[i];
        out += w2[i];
    }
    out += w1.substr(i);
    out += w2.substr(i);
    return out;
}

