reference_solution:
string gcdOfStrings(string w1, string w2) {
    if (w1 + w2 != w2 + w1) return "";
    // The two strings are the same block repeated, so the block is as long
    // as the greatest common divisor of their lengths.
    size_t a = w1.size();
    size_t b = w2.size();
    while (b != 0) {
        size_t t = a % b;
        a = b;
        b = t;
    }
    return w1.substr(0, a);
}

