reference_solution:
vector<int> kidsWithCandies(vector<int>& candies, vector<int>& queries) {
    vector<int> sorted = candies;
    sort(sorted.begin(), sorted.end());
    vector<int> out;
    for (int q : queries) {
        out.push_back((int)(sorted.end() - upper_bound(sorted.begin(), sorted.end(), q)));
    }
    return out;
}

