string compressString(vector<string>& chars) {
    string all;
    for (const string& s : chars) all += s;
    string out;
    for (size_t i = 0; i < all.size();) {
        size_t j = i;
        while (j < all.size() && all[j] == all[i]) j++;
        out += all[i];
        if (j - i > 1) out += to_string(j - i);
        i = j;
    }
    return out;
}

