reference_solution:
int maxOperations(vector<int>& nums, int k) {
    vector<int> sorted = nums;
    sort(sorted.begin(), sorted.end());
    int count = 0;
    int l = 0;
    int r = (int)sorted.size() - 1;
    while (l < r) {
        int sum = sorted[l] + sorted[r];
        if (sum == k) { count++; l++; r--; }
        else if (sum < k) l++;
        else r--;
    }
    return count;
}

