reference_solution:
int findTheDifference(vector<int>& nums1, vector<int>& nums2) {
    unordered_map<int, int> count;
    for (int x : nums1) count[x]++;
    for (int x : nums2) count[x]--;
    for (const auto& [value, n] : count) {
        if (n != 0) return value;
    }
    return 0;
}

