bool uniqueOccurrences(vector<int>& nums) {
    unordered_map<int, int> count;
    for (int x : nums) count[x]++;
    unordered_set<int> seen;
    for (const auto& [value, n] : count) {
        if (!seen.insert(n).second) return false;
    }
    return true;
}

