reference_solution:
bool areCloseStrings(string word1, string word2) {
    if (word1.size() != word2.size()) return false;
    int a[26] = {0};
    int b[26] = {0};
    for (char c : word1) a[c - 'a']++;
    for (char c : word2) b[c - 'a']++;
    for (int i = 0; i < 26; i++) {
        if ((a[i] > 0) != (b[i] > 0)) return false;
    }
    vector<int> fa;
    vector<int> fb;
    for (int i = 0; i < 26; i++) {
        if (a[i]) fa.push_back(a[i]);
        if (b[i]) fb.push_back(b[i]);
    }
    sort(fa.begin(), fa.end());
    sort(fb.begin(), fb.end());
    return fa == fb;
}

