int equalPairs(vector<vector<int>>& pairs) {
    int n = (int)pairs.size();
    int count = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (pairs[i][j] == pairs[j][i]) count++;
        }
    }
    return count;
}

