vector<int> asteroidCollision(vector<int>& asteroids) {
    vector<int> stack;
    for (int a : asteroids) {
        bool alive = true;
        while (alive && a < 0 && !stack.empty() && stack.back() > 0) {
            if (stack.back() < -a) {
                stack.pop_back();
            } else if (stack.back() == -a) {
                stack.pop_back();
                alive = false;
            } else {
                alive = false;
            }
        }
        if (alive) stack.push_back(a);
    }
    return stack;
}

