string decodeString(string s) {
    stack<string> parts;
    stack<int> counts;
    string current;
    int count = 0;
    for (char c : s) {
        if (isdigit((unsigned char)c)) {
            count = count * 10 + (c - '0');
        } else if (c == '[') {
            parts.push(current);
            counts.push(count);
            current.clear();
            count = 0;
