vector<int> numberOfRecentCalls(vector<int>& calls) {
    vector<int> out;
    int first = 0;
    for (int i = 0; i < (int)calls.size(); i++) {
        while (calls[i] - calls[first] > 3000) first++;
        out.push_back(i - first + 1);
    }
    return out;
}

