reference_solution:
string dota2Senate(vector<string>& actions) {
    int n = (int)actions.size();
    queue<int> radiant;
    queue<int> dire;
    for (int i = 0; i < n; i++) {
        if (actions[i] == "R") radiant.push(i);
        else dire.push(i);
    }
    while (!radiant.empty() && !dire.empty()) {
        int r = radiant.front();
        radiant.pop();
        int d = dire.front();
        dire.pop();
        if (r < d) radiant.push(r + n);
        else dire.push(d + n);
    }
    return radiant.empty() ? "Dire" : "Radiant";
}

