reference_solution:
int maxTwinSum(ListNode* head) {
    vector<int> values;
    for (ListNode* node = head; node; node = node->next) values.push_back(node->val);
    int best = 0;
    int left = 0;
    int right = (int)values.size() - 1;
    while (left < right) {
        best = max(best, values[left] + values[right]);
        left++;
        right--;
    }
    return best;
}

