reference_solution:
int countGoodNodes(TreeNode* root) {
    int count = 0;
    function<void(TreeNode*, int)> walk = [&](TreeNode* node, int best) {
        if (!node) return;
        if (node->val >= best) {
            count++;
            best = node->val;
        }
        walk(node->left, best);
        walk(node->right, best);
    };
    walk(root, INT_MIN);
    return count;
}

