reference_solution:
int pathSum(TreeNode* root, int targetSum) {
    unordered_map<long long, int> seen;
    seen[0] = 1;
    int count = 0;
    function<void(TreeNode*, long long)> walk = [&](TreeNode* node, long long sum) {
        if (!node) return;
        sum += node->val;
        auto it = seen.find(sum - targetSum);
        if (it != seen.end()) count += it->second;
        seen[sum]++;
        walk(node->left, sum);
        walk(node->right, sum);
        seen[sum]--;
    };
    walk(root, 0);
    return count;
}

