reference_solution:
int longestZigZag(TreeNode* root) {
    int best = 0;
    function<void(TreeNode*, int, int)> walk =
        [&](TreeNode* node, int previousDirection, int length) {
            if (!node) return;
            best = max(best, length);
            if (node->left) {
                walk(node->left, 0, previousDirection == 0 ? 1 : length + 1);
            }
            if (node->right) {
                walk(node->right, 1, previousDirection == 1 ? 1 : length + 1);
            }
        };
    walk(root, -1, 1);
    return best;
}

