bool holds(TreeNode* node, int value) {
    if (!node) return false;
    if (node->val == value) return true;
    return holds(node->left, value) || holds(node->right, value);
}

int lowestCommonAncestor(TreeNode* root, int p, int q) {
    if (!root) return -1;
    if (root->val == p || root->val == q) return root->val;
    bool pLeft = holds(root->left, p);
    bool qLeft = holds(root->left, q);
    bool pRight = holds(root->right, p);
    bool qRight = holds(root->right, q);
    if (pLeft && qLeft) return lowestCommonAncestor(root->left, p, q);
    if (pRight && qRight) return lowestCommonAncestor(root->right, p, q);
    // One of them is here and the other is in the other subtree.
    return root->val;
}

