int maxLevelSum(TreeNode* root) {
    if (!root) return 0;
    queue<TreeNode*> pending;
    pending.push(root);
    int best = INT_MIN;
    while (!pending.empty()) {
        int size = (int)pending.size();
        int sum = 0;
        for (int i = 0; i < size; i++) {
            TreeNode* node = pending.front();
            pending.pop();
            sum += node->val;
            if (node->left) pending.push(node->left);
            if (node->right) pending.push(node->right);
        }
        best = max(best, sum);
    }
    return best;
}

