bool canVisitAllRooms(vector<vector<int>>& rooms, int start) {
    vector<bool> seen(rooms.size(), false);
    stack<int> pending;
    pending.push(start);
    seen[start] = true;
    int visited = 1;
    while (!pending.empty()) {
        int room = pending.top();
        pending.pop();
        for (int key : rooms[room]) {
            if (!seen[key]) {
                seen[key] = true;
                visited++;
                pending.push(key);
            }
        }
    }
    return visited == (int)rooms.size();
}

