int findCircleNum(vector<vector<int>>& isConnected) {
    int n = (int)isConnected.size();
    vector<bool> seen(n, false);
    int provinces = 0;
    for (int i = 0; i < n; i++) {
        if (seen[i]) continue;
        provinces++;
        stack<int> pending;
        pending.push(i);
        seen[i] = true;
        while (!pending.empty()) {
            int city = pending.top();
            pending.pop();
            for (int j = 0; j < n; j++) {
                if (isConnected[city][j] == 1 && !seen[j]) {
                    seen[j] = true;
                    pending.push(j);
                }
            }
        }
    }
    return provinces;
}

