vector<int> findReorder(vector<int>& paths) {
    int n = (int)paths.size();
    vector<vector<int>> children(n);
    for (int i = 0; i < n; i++) {
        if (i != paths[i]) children[paths[i]].push_back(i);
    }
    vector<int> order;
    vector<bool> seen(n, false);
    stack<int> pending;
    pending.push(0);
    seen[0] = true;
    while (!pending.empty()) {
        int city = pending.top();
        pending.pop();
        order.push_back(city);
        for (int child : children[city]) {
            if (!seen[child]) {
                seen[child] = true;
                pending.push(child);
            }
        }
    }
    reverse(order.begin(), order.end());
    vector<int> answer(n, 0);
    for (int i = 0; i + 1 < (int)order.size(); i++) {
        answer[order[i]] = order[i + 1];
    }
    if (!order.empty()) answer[order.back()] = 0;
    return answer;
}

