vector<double> calcEquation(vector<vector<string>>& equations, vector<double>& values) {
    unordered_map<string, unordered_map<string, double>> graph;
    for (int i = 0; i < (int)equations.size(); i++) {
        const string& a = equations[i][0];
        const string& b = equations[i][1];
        graph[a][b] = values[i];
        graph[b][a] = 1.0 / values[i];
    }
    vector<double> out;
    for (const auto& equation : equations) {
        const string& from = equation[0];
        const string& to = equation[1];
        double answer = 0.0;
        if (from == to) {
            answer = 1.0;
        } else {
            // ratio[x] is the value of `from / x`.
            unordered_map<string, double> ratio;
            ratio[from] = 1.0;
            stack<pair<string, double>> pending;
            pending.push({from, 1.0});
            while (!pending.empty()) {
                auto [node, value] = pending.top();
                pending.pop();
                if (node == to) {
                    answer = value;
                    break;
                }
                for (const auto& edge : graph[node]) {
                    if (ratio.count(edge.first)) continue;
                    double next = value * edge.second;
                    ratio[edge.first] = next;
                    pending.push({edge.first, next});
                }
            }
        }
        out.push_back(answer);
    }
    return out;
}

