int nearestExit(vector<vector<char>>& maze, vector<int>& entrance) {
    int rows = (int)maze.size();
    int cols = (int)maze[0].size();
    vector<vector<int>> steps(rows, vector<int>(cols, -1));
    queue<pair<int, int>> pending;
    pending.push({entrance[0], entrance[1]});
    steps[entrance[0]][entrance[1]] = 0;
    int dr[4] = {-1, 1, 0, 0};
    int dc[4] = {0, 0, -1, 1};
    while (!pending.empty()) {
        auto [r, c] = pending.front();
        pending.pop();
        for (int d = 0; d < 4; d++) {
            int nr = r + dr[d];
            int nc = c + dc[d];
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
            if (maze[nr][nc] != '.') continue;
            if (steps[nr][nc] != -1) continue;
            steps[nr][nc] = steps[r][c] + 1;
            if (nr == 0 || nc == 0 || nr == rows - 1 || nc == cols - 1) {
                return steps[nr][nc];
            }
            pending.push({nr, nc});
        }
    }
    return -1;
}

