int findKthLargest(vector<int>& nums, int k) {
    // A smallest-first heap keeps the k biggest: the one it throws away is
    // always the smallest of the ones kept.
    priority_queue<int, vector<int>, greater<int>> heap;
    for (int x : nums) {
        heap.push(x);
        if ((int)heap.size() > k) heap.pop();
    }
    return heap.top();
}

