vector<int> smallestNumberInInfiniteSet(vector<string>& operations, vector<int>& values) {
    int next = 1;
    priority_queue<int, vector<int>, greater<int>> added;
    vector<int> out;
    for (size_t i = 0; i < operations.size(); i++) {
        if (operations[i] == "add") {
            int x = values[i];
            // A number that has not been handed out yet is still in the set,
            // so putting it back changes nothing.
            if (x >= next) continue;
            added.push(x);
        } else {
            if (!added.empty() && added.top() < next) {
                out.push_back(added.top());
                added.pop();
            } else {
                out.push_back(next);
                next++;
            }
        }
    }
    return out;
}

