int maximumSubsequenceScore(vector<int>& score, vector<int>& age) {
    sort(score.rbegin(), score.rend());
    sort(age.rbegin(), age.rend());
    priority_queue<int> available;
    int i = 0;
    int total = 0;
    for (int a : age) {
        while (i < (int)score.size() && score[i] > a) {
            available.push(score[i]);
            i++;
        }
        if (!available.empty()) {
            total += a + available.top();
            available.pop();
        }
    }
