int totalCost(vector<int>& costs, int k, int workers) {
    int low = 0;
    int high = (int)costs.size() - 1;
    long long total = 0;
    for (int hired = 0; hired < k; hired++) {
        // The cheaper of the two ends is always the right one to take.
        if (costs[low] <= costs[high]) total += costs[low++];
        else total += costs[high--];
    }
    total += (long long)k * workers;
    return (int)total;
}

