int worstCase(int n) {
    if (n <= 1) return 1;
    // Guess in the middle, so the larger side keeps at most half of what is
    // left.
    return 1 + worstCase((n - 1 + 1) / 2);
}

int guessNumber(int n) {
    return worstCase(n);
}

