reference_solution:
int successfulPairs(vector<int>& spells, vector<int>& potions, int success) {
    sort(potions.begin(), potions.end());
    int count = 0;
    for (int s : spells) {
        auto it = lower_bound(potions.begin(), potions.end(), success - s + 1);
        count += (int)(potions.end() - it);
    }
    return count;
}

