reference_solution:
int findPeakElement(vector<int>& nums) {
    // The first peak, so the answer is one thing and not several.
    for (int i = 0; i < (int)nums.size(); i++) {
        bool higherThanLeft = i == 0 || nums[i] > nums[i - 1];
        bool higherThanRight = i == (int)nums.size() - 1 || nums[i] > nums[i + 1];
        if (higherThanLeft && higherThanRight) return i;
    }
    return -1;
}

