int minEatingSpeed(vector<int>& piles, int h) {
    long long low = 1;
    long long high = 0;
    for (int p : piles) high = max(high, (long long)p);
    while (low < high) {
        long long mid = low + (high - low) / 2;
        long long hours = 0;
        for (int p : piles) hours += (p + mid - 1) / mid;
        if (hours > h) low = mid + 1;
        else high = mid;
    }
    return (int)low;
}

