vector<string> letterCombinations(string digits) {
    const string keys[10] = {
        "", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"
    };
    vector<string> out;
    if (digits.empty()) return out;
    string current;
    function<void(size_t)> build = [&](size_t index) {
        if (index == digits.size()) {
            out.push_back(current);
            return;
        }
        for (char c : keys[digits[index] - '0']) {
            current += c;
            build(index + 1);
            current.pop_back();
        }
    };
    build(0);
    return out;
}

