vector<vector<int>> combinationSum3(int k, int n) {
    vector<vector<int>> out;
    vector<int> current;
    function<void(int, int)> build = [&](int start, int remaining) {
        if ((int)current.size() == k) {
            if (remaining == 0) out.push_back(current);
            return;
        }
        for (int value = start; value <= 9; value++) {
            if (value > remaining) break;
            current.push_back(value);
            build(value + 1, remaining - value);
            current.pop_back();
        }
    };
    build(1, n);
    return out;
}

