int tribonacci(int n) {
    if (n == 0) return 0;
    if (n <= 2) return 1;
    long long a = 0;
    long long b = 1;
    long long c = 1;
    for (int i = 3; i <= n; i++) {
        long long next = a + b + c;
        a = b;
        b = c;
        c = next;
    }
    return (int)c;
}

