int minCostClimbingStairs(vector<int>& cost) {
    int n = (int)cost.size();
    vector<int> best(n + 1, 0);
    for (int i = 2; i <= n; i++) {
        best[i] = min(best[i - 1] + cost[i - 1], best[i - 2] + cost[i - 2]);
    }
    return best[n];
}

