int dominoAndTrominoTiling(int n) {
    const long long MOD = 1000000007;
    vector<long long> ways(n + 1, 0);
    ways[0] = 1;
    if (n >= 1) ways[1] = 1;
    if (n >= 2) ways[2] = 2;
    for (int i = 3; i <= n; i++) {
        ways[i] = (2 * ways[i - 1] + ways[i - 3]) % MOD;
    }
    return (int)ways[n];
}

