reference_solution:
int maxProfit(vector<int>& prices, int fee) {
    int holding = -prices[0];
    int free = 0;
    for (int i = 1; i < (int)prices.size(); i++) {
        int previousHolding = holding;
        holding = max(holding, free - prices[i]);
        free = max(free, previousHolding + prices[i] - fee);
    }
    return free;
}

