int minFlips(int a, int b, int c) {
    int flips = 0;
    for (int i = 0; i < 10; i++) {
        int bitA = (a >> i) & 1;
        int bitB = (b >> i) & 1;
        int bitC = (c >> i) & 1;
        if (bitC == 0) {
            flips += bitA + bitB;
        } else if (bitA == 0 && bitB == 0) {
            flips += 1;
        }
    }
    return flips;
}

