vector<int> trieOperations(vector<string>& operations, vector<string>& arguments) {
    struct Node {
        map<char, int> children;
        bool isWord = false;
    };
    vector<Node> nodes(1);
    vector<int> out;
    for (size_t i = 0; i < operations.size(); i++) {
        const string& op = operations[i];
        const string& word = arguments[i];
        if (op == "insert") {
            int node = 0;
            for (char c : word) {
                if (!nodes[node].children.count(c)) {
                    int index = (int)nodes.size();
                    nodes[node].children[c] = index;
                    nodes.push_back(Node());
                }
                node = nodes[node].children[c];
            }
            if (nodes[node].isWord) {
                out.push_back(0);
            } else {
                nodes[node].isWord = true;
                out.push_back(1);
            }
        } else if (op == "search") {
            int node = 0;
            bool found = true;
            for (char c : word) {
                if (!nodes[node].children.count(c)) {
                    found = false;
                    break;
                }
                node = nodes[node].children[c];
            }
            out.push_back(found && nodes[node].isWord ? 1 : 0);
        } else {
            int node = 0;
            bool found = true;
            for (char c : word) {
                if (!nodes[node].children.count(c)) {
                    found = false;
                    break;
                }
                node = nodes[node].children[c];
            }
            out.push_back(found ? 1 : 0);
        }
    }
    return out;
}

