vector<vector<string>> suggestedProducts(vector<string>& products, string searchWord) {
    vector<vector<string>> out;
    sort(products.begin(), products.end());
    int low = 0;
    int high = (int)products.size() - 1;
    for (size_t i = 0; i < searchWord.size(); i++) {
        char c = searchWord[i];
        while (low <= high && products[low][i] != c) low++;
        while (low <= high && products[high][i] != c) high--;
        vector<string> matches;
        for (int j = low; j <= high && (int)matches.size() < 3; j++) {
            matches.push_back(products[j]);
        }
        out.push_back(matches);
    }
    return out;
}

